def esc(v): return html.escape(str(v),quote=True)
def icon(n): return f'<i class="fa-solid {n}" aria-hidden="true"></i>'
def link(h,t,c='btn',ic=''): return f'<a class="{c}" href="{h}">{icon(ic) if ic else ""}{t}</a>'
def badge(t,c=''): return f'<span class="badge {c}">{t}</span>'
def card(t,b='',c=''): return f'<section class="card {c}">'+(f'<h2>{t}</h2>' if t else '')+f'{b}</section>'
def note(t,c=''): return f'<div class="note {c}">{icon("fa-circle-info")}<div>{t}</div></div>'
def heading(t,d='',action=''): return f'<div class="page-heading"><div><div class="eyebrow">中南大学 · 智慧后勤</div><h1>{t}</h1><p>{d}</p></div>{action}</div>'
def table(headers,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def field(label,value='',kind='text',name='',options=None,required=True):
 name=name or 'field'+str(len(label))
 req=' required' if required else ''
 if options: control=f'<select id="{name}" name="{name}">'+''.join(f'<option>{esc(x)}</option>' for x in options)+'</select>'
 elif kind=='textarea': control=f'<textarea id="{name}" name="{name}" rows="5"{req}>{esc(value)}</textarea>'
 else: control=f'<input id="{name}" name="{name}" type="{kind}" value="{esc(value)}"{req}>'
 return f'<div class="field"><label for="{name}">{label}{" <em>*</em>" if required else ""}</label>{control}</div>'
