importjs='''<script>
document.addEventListener('DOMContentLoaded',()=>{let f=document.querySelector('#schedule-import');f.addEventListener('submit',async e=>{e.preventDefault();let file=document.getElementById('schedule-file').files[0];if(!file)return;let text=(await file.text()).replace(/^\\uFEFF/,'').trim(),rows=text.split(/\\r?\\n/).map(r=>r.split(','));let headers=['会议主题','开始时间','结束时间','会议地点','参会工号','提前分钟'];let errors=[];if(headers.some((h,i)=>rows[0]?.[i]!==h))errors.push('请使用指定模板，保持六列中文表头不变');if(rows.length<2)errors.push('文件没有会议数据');rows.slice(1).forEach((r,i)=>{if(r.length!==6||r.some(x=>!x.trim()))errors.push('第'+(i+2)+'行存在缺失字段');else if(!/^\\d{8}(;\\d{8})*$/.test(r[4]))errors.push('第'+(i+2)+'行工号需为8位数字，多个工号用分号分隔');else if(![15,30,60].includes(Number(r[5])))errors.push('第'+(i+2)+'行提前分钟仅支持15、30、60');else if(isNaN(Date.parse(r[1]))||isNaN(Date.parse(r[2]))||Date.parse(r[2])<=Date.parse(r[1]))errors.push('第'+(i+2)+'行开始或结束时间无效');else if(Date.parse(r[1])-Date.now()<Number(r[5])*60000)errors.push('第'+(i+2)+'行开始时间或提醒时点已过');});store('import',{rows:rows.slice(1),errors});location.href=errors.length?'meeting-import-error.html':'meeting-import-preview.html'});})
</script>'''
